@import url('https://fonts.googleapis.com/css2?family=Maven+Pro:wght@400;500;600;700&family=Roboto:wght@300;400;500;700&display=swap');

/*
   home: pageId_k5sdd5jnfai
   facility: pageId_tey70kz3dgo
   penal analytics: pageId_jgbyv2tveag
*/

:root {
  --c-bg-active-link: #ea5050;
  --c-text-active-link: white;
  --c-menu-highlight: #ea5050;
  --c-tooltip-bg: #fdf7f4;
  --c-tooltip-counter: #e67d72;
  --c-tooltip-font: #282527;
  --c-gray: #c9c5c5;
}

.pageId_jgbyv2tveag,
.pageId_tey70kz3dgo,
.pageId_k5sdd5jnfai {
  height: auto;
  overflow: visible;
}

/*! ---- RESET ---- */
.markdown-viewer:has(.customPage) > p:not(.hero-analytics-wrapper p) {
  margin: 0;
}
.page-viewer {
  padding: 0;
}

.page-viewer.document-viewer {
  padding: 0;
}

.page-viewer .map-container {
  max-width: 1200px;
  width: 100%;
  height: 440px;
}

/*! MAIN WRAPPER */

.main-wrapper .footer-nav {
  display: none !important;
}

.main-wrapper footer {
  border-top: none !important;
}

footer {
  margin: 0;
  padding: 0;
}

.main-wrapper {
  padding-bottom: 0;
}

.main-wrapper,
.panels-layout {
  background-color: #f5f5f4;
}

/* DATABASE FONTS  */
/* Cards  */
.documents-list .search-list input,
.entity-metadata dt,
.entity-metadata,
.item-metadata,
.item,
.item-info {
  font-family: 'Roboto', sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 24px;
  color: #575154;
}

.item-info {
  background-color: #36406a;
  margin-bottom: 16px;
}

.item-name {
  font-family: 'Maven Pro', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 20px;
  color: #f5f5f4;
  text-transform: uppercase;
}

.item-metadata dd.item-current-sort {
  background-color: #eee;
  margin-left: -3px;
  padding: 3px 3px 1px;
  opacity: 0.5;
  border-radius: 2px;
}

/* Sidebar  */
.multiselectItem-name {
  font-family: 'Maven Pro', sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 15px;
  text-transform: uppercase;
}

/* Sidebar  */
.side-panel {
  background-color: #eee;
}

.multiselectChild .multiselectItem-name {
  font-family: 'Roboto', sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 15px;
  color: #575154;
  text-transform: none;
  margin-bottom: 4px;
}

.blank-state h4 {
  font-family: 'Roboto', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 15px;
  color: #575154;
}

.blank-state p {
  font-family: 'Roboto', sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 20px;
  color: #575154;
  margin-bottom: 4px;
}

/* Links  */
.paginator span {
  font-size: 14px;
}

.blank-state a,
.view .multiline li a,
.paginator a {
  color: #ea5050;
  border-bottom: 1px solid #ea5050;
  font-family: 'Roboto', sans-serif;
  font-size: 14px;
}

.documents-counter {
  font-family: 'Roboto', sans-serif;
  font-weight: 500;
  font-size: 14px;
}

.search-box .search-tips,
.Dropdown-option,
.Dropdown-option__item {
  color: #ea5050 !important;
  font-family: 'Roboto', sans-serif;
  font-weight: 500;
  font-size: 14px;
  border-bottom: none;
}
.search-box .search-tips {
  padding: 6px 0;
}

.search-box .search-tips:hover {
  color: #f3cbbc !important;
}

.blank-state a:hover {
  color: #f3cbbc;
  border-bottom: none;
}
.view .multiline li a:hover {
  color: #f3cbbc;
  border-bottom: 1px solid #f3cbbc;
}

.documents-counter b {
  font-family: 'Roboto', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 15px;
  color: #575154;
}

/* Metadata  */
dl.metadata-type-select dt,
.entity-viewer .view dt,
.sidepanel-body .view dt,
.content-header.content-header-entity .item-name,
.entity-metadata dt {
  font-family: 'Maven Pro', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 28px;
  color: #1a1a1a;
  text-transform: uppercase;
  opacity: 1;
}

.item-metadata dt {
  font-family: 'Maven Pro', sans-serif;
  font-weight: 400;
  font-size: 14px;
  line-height: 25px;
  letter-spacing: -0.04em;
}

.side-panel.library-filters .sidepanel-title {
  font-family: 'Maven Pro', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 46px;
  color: #1a1a1a;
  text-transform: uppercase;
  opacity: 1;
}

/* buttons */
button.btn.btn-success,
label.btn.btn-success {
  background-color: #ea5050;
}

.sidepanel-footer .btn.btn-primary,
button.btn.btn-primary.btn-export {
  background-color: #e67d72;
  border: none;
}

.sidepanel-footer .btn-label {
  background-color: transparent;
}

.sidepanel-header {
  background-color: #f5f5f4;
}

a.btn.btn-default.btn-load-more {
  border-color: #e67d72;
  color: #575154;
  border-radius: 31px;
}
a.btn.btn-default.btn-load-more:hover {
  background-color: #e67d72;
}

.filelist .btn {
  border-color: #e67d72;
  background-color: #e67d72;
  color: #eee;
  border-radius: 31px;
}

a.file-download.btn.btn-outline-secondary {
  background-color: transparent;
  border-color: #ea5050;
  color: #ea5050;
  border-radius: 31px;
}

.relationships-graph .item-collapsed .item-actions {
  padding: 16px 10px;
}

.item-actions .btn,
.item-actions .btn-color {
  font-size: 12px;
  border: none;
}

.multiselectItem-icon .checkbox-checked,
.multiselectItem-icon .checkbox-group,
.multiselectItem-icon .checkbox-partial {
  color: #5cb85cb3;
}

.documents-list {
  margin-bottom: 60px;
}

