/* LEVEL-2 STYLES
–––––––––––––––––––––––––––––––––––––––––––––––––– */
.level-2-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  padding-left: 0;
  padding-right: 0px;
}

.level-2-wrapper::after {
  display: none;
  content: '';
  position: absolute;
  left: -20px;
  bottom: -20px;
  width: calc(100% + 20px);
  height: 2px;
  background: #c9c5c5;
}

.level-2-wrapper li {
  position: relative;
}

.level-2-wrapper > li::before {
  content: '';
  position: absolute;
  top: 38px;
  left: 15px;
  width: 50%;
  height: 1px;
  background: #c9c5c5;
}

